mapper.sql:
WHERE m.state = '1'

    AND m.userId = #{userId}


    AND m.deviceId = #{deviceId}


    AND m.messageType = #{messageType}


    AND d.deviceName = #{deviceName}


    AND m.createTime  >=  #{startTime}


    AND m.createTime  <=  #{endTime}


    AND m.sender = #{sender}


    AND m.roleId = #{roleId}


    AND m.sessionId = #{sessionId}


    AND m.source = #{source}

mapper.select:
SELECT , m.userId, u.username, u.name AS ownerName
FROM sys_message m
LEFT JOIN sys_device d ON m.deviceId = d.deviceId
LEFT JOIN sys_role r ON m.roleId = r.roleId
LEFT JOIN sys_user u ON m.userId = u.userId
WHERE m.state = '1'


    AND m.userId = #{scopeUserId} AND d.userId = #{scopeUserId}

AND m.deviceId = #{filter.deviceId}
AND d.deviceName LIKE CONCAT('%',#{filter.deviceName},'%')
AND m.sender = #{filter.sender}
AND m.messageType = #{filter.messageType}
AND m.roleId = #{filter.roleId}
AND m.createTime  >=  #{filter.startTime}

AND m.createTime  <  DATE_ADD(#{filter.endTime}, INTERVAL 1 SECOND)
AND m.sessionId = #{filter.sessionId}
AND m.source = #{filter.source}
AND m.message LIKE CONCAT('%',#{filter.keyword},'%')

    ORDER BY m.createTime ASC, m.messageId ASC
    ORDER BY m.createTime DESC, m.messageId DESC
